loadstring(game:HttpGet('https://raw.githubusercontent.com/CosmicHubProductions/OldProject/refs/heads/main/Lua'))()

getgenv().Enabled = true

local Old
Old = hookmetamethod(game, "__namecall", newcclosure(function(Self, ...)
 local Args = {...}
 local Method = getnamecallmethod()
 if Method == "FireServer" and Self.Name == "Reliable" and getgenv().Enabled and not checkcaller() then
  Args[2][1][2] = -9e999
  return Old(Self, table.unpack(Args))
 end
 return Old(Self, ...)
end))
